-- 系统文档模板版本（只增不改）
INSERT INTO document_template_versions (id, template_id, version, name, description, groups, content_hash, created_at) VALUES (1, 1, 1, 'Billing Note / ใบวางบิล', '泰国「ใบวางบิล / Billing Note」（也称 ใบแจ้งหนี้รวม、ใบวางบิล/ใบแจ้งหนี้）：供应商向客户汇总列出一批已开具的发票或税务发票（Invoice / Tax Invoice），请客户按约定日期付款。典型特征：标题含 ใบวางบิล 或 Billing Note；正文是一张发票清单，每行一张发票，列有 วันที่ใบแจ้งหนี้ / Invoice Date、เลขที่ใบแจ้งหนี้/ใบกำกับภาษี / Invoice No.、จำนวนก่อนภาษีมูลค่าเพิ่ม / Amount、ภาษีมูลค่าเพิ่ม / Vat、จำนวนเงินรวม / Total Amount；底部有「รวม N ฉบับ」张数、รวมยอดชำระทั้งสิ้น 应付总额、泰文大写金额、收款银行账号，以及 ผู้รับวางบิล / Received By、กำหนดชำระ / Payment Date 签收栏。与单张发票的区别：明细行是「发票」而不是「货品」。', '[{"key": "document", "name": "Document / ข้อมูลเอกสาร", "description": "单据头部信息", "items": [{"kind": "field", "key": "billing_no", "name": "Billing No. / เลขที่ใบวางบิล", "description": "账单（ใบวางบิล）自身的编号，标注 เลขที่ / No.；注意不是清单中某张发票的编号。很多账单没有编号，没有时填 null", "type": "string", "required": false}, {"kind": "field", "key": "billing_date", "name": "Date / วันที่", "description": "账单日期，标注 วันที่ / Date，通常在客户名称右侧。按原文保留（如 22.02.2024），不转换佛历或公历", "type": "string", "required": true}, {"kind": "field", "key": "invoice_count", "name": "Invoice Count / จำนวนฉบับ", "description": "清单中的发票张数，原文形如「รวม 1 ฉบับ」，只填数字", "type": "integer", "required": false}, {"kind": "field", "key": "payment_due_date", "name": "Payment Date / กำหนดชำระ", "description": "约定付款日期，标注 กำหนดชำระ / Payment Date / Due Date，常为手写；空白或只有虚线时填 null。按原文保留", "type": "string", "required": false}, {"kind": "field", "key": "received_date", "name": "Received Date / วันที่รับวางบิล", "description": "客户签收账单的日期，标注 วันที่รับวางบิล / Received Date，常为手写；空白时填 null。按原文保留", "type": "string", "required": false}]}, {"key": "issuer", "name": "Issuer / ผู้วางบิล", "description": "开具账单的供应商（收款方），信息通常在页面顶部抬头与 Logo 旁", "items": [{"kind": "field", "key": "name", "name": "Company Name / ชื่อบริษัท", "description": "供应商泰文全称，如「ห้างหุ้นส่วนจำกัด …」「บริษัท … จำกัด」，按原文保留", "type": "string", "required": true}, {"kind": "field", "key": "name_en", "name": "English Name / ชื่อภาษาอังกฤษ", "description": "供应商英文名称（常在 Logo 下方或泰文名下一行），没有填 null", "type": "string", "required": false}, {"kind": "field", "key": "tax_id", "name": "Tax ID / เลขประจำตัวผู้เสียภาษี", "description": "供应商 13 位纳税人识别号，标注 เลขประจำตัวผู้เสียภาษีอากร / Tax ID；只填数字，不含空格和横线", "type": "string", "required": false}, {"kind": "field", "key": "branch", "name": "Branch / สาขา", "description": "供应商分支机构，如「สำนักงานใหญ่」（总公司）或「สาขาที่ 00001」，按原文保留", "type": "string", "required": false}, {"kind": "field", "key": "address", "name": "Address / ที่อยู่", "description": "供应商地址全文，合并为一行", "type": "string", "required": false}, {"kind": "field", "key": "phone", "name": "Phone / โทร", "description": "供应商电话，标注 โทร / Tel；多个号码用英文逗号分隔", "type": "string", "required": false}, {"kind": "field", "key": "email", "name": "Email / อีเมล", "description": "供应商电子邮箱，标注 อีเมล์ / Email", "type": "string", "required": false}]}, {"key": "customer", "name": "Customer / ลูกค้า", "description": "收到账单、需要付款的客户，标注 ชื่อลูกค้า / Customers", "items": [{"kind": "field", "key": "name", "name": "Customer Name / ชื่อลูกค้า", "description": "客户名称全文，按原文保留", "type": "string", "required": true}, {"kind": "field", "key": "tax_id", "name": "Tax ID / เลขประจำตัวผู้เสียภาษี", "description": "客户 13 位纳税人识别号；只填数字，没有填 null", "type": "string", "required": false}, {"kind": "field", "key": "branch", "name": "Branch / สาขา", "description": "客户分支机构，如「สำนักงานใหญ่」，没有填 null", "type": "string", "required": false}, {"kind": "field", "key": "address", "name": "Address / ที่อยู่", "description": "客户地址全文，合并为一行，没有填 null", "type": "string", "required": false}]}, {"key": "invoices", "name": "Invoice List / รายการใบแจ้งหนี้", "description": "账单所汇总的发票清单，标题常为「ได้รับวางบิล ตามรายการต่อไปนี้」", "items": [{"kind": "table", "key": "items", "name": "Invoices / ใบแจ้งหนี้", "description": "每一行对应一张发票或税务发票；忽略空白行，也不要把银行账号、合计行当作明细行；文件中原件（ต้นฉบับ）与副本（สำเนา）页内容相同时只输出一份", "columns": [{"key": "item_no", "name": "Item / ลำดับที่", "description": "行序号，标注 ลำดับที่ / Item", "type": "integer", "required": false}, {"key": "invoice_date", "name": "Invoice Date / วันที่ใบแจ้งหนี้", "description": "该张发票的日期，标注 วันที่ใบแจ้งหนี้/ใบกำกับภาษี / Invoice Date，按原文保留", "type": "string", "required": false}, {"key": "invoice_no", "name": "Invoice No. / เลขที่ใบแจ้งหนี้", "description": "该张发票的编号，标注 เลขที่ใบแจ้งหนี้และ/หรือใบกำกับภาษี / Invoice/Tax Invoice No.，如 INV2024020872", "type": "string", "required": true}, {"key": "product", "name": "Product / สินค้า", "description": "该张发票对应的商品或摘要，标注 สินค้า / Product，没有填 null", "type": "string", "required": false}, {"key": "delivery_date", "name": "Send Date / วันที่ส่งสินค้า", "description": "送货日期，标注 วันที่ส่งสินค้า / Send Date，空白填 null", "type": "string", "required": false}, {"key": "amount_before_vat", "name": "Amount / ก่อนภาษีมูลค่าเพิ่ม", "description": "不含增值税金额，标注 จำนวนก่อนภาษีมูลค่าเพิ่ม / Amount", "type": "amount", "required": false}, {"key": "vat_amount", "name": "VAT / ภาษีมูลค่าเพิ่ม", "description": "增值税额，标注 ภาษีมูลค่าเพิ่ม / Vat", "type": "amount", "required": false}, {"key": "total_amount", "name": "Total Amount / จำนวนเงินรวม", "description": "该张发票含税合计，标注 จำนวนเงินรวม / Total Amount", "type": "amount", "required": true}]}]}, {"key": "summary", "name": "Summary / สรุปยอด", "description": "账单底部的合计信息", "items": [{"kind": "field", "key": "total_amount", "name": "Grand Total / รวมยอดชำระทั้งสิ้น", "description": "应付总额，标注 รวมยอดชำระทั้งสิ้น (บาท)；直接取原文数字，不要自行相加", "type": "amount", "required": true}, {"kind": "field", "key": "total_amount_text", "name": "Amount in Words / จำนวนเงินตัวอักษร", "description": "泰文大写金额，标注 (ตัวอักษร)，如「หกพันหกร้อยหกสิบหกบาทสามสิบเอ็ดสตางค์」，按原文保留", "type": "string", "required": false}]}, {"key": "payment", "name": "Payment / การชำระเงิน", "description": "收款银行账户，常写在发票清单下方，如「เลขที่บัญชีสำหรับโอนเงิน ธนาคาร … 」", "items": [{"kind": "field", "key": "bank_name", "name": "Bank / ธนาคาร", "description": "收款银行名称，如「ธนาคาร กสิกรไทย」", "type": "string", "required": false}, {"kind": "field", "key": "account_no", "name": "Account No. / เลขที่บัญชี", "description": "收款银行账号，只保留数字和横线，去掉引号等符号", "type": "string", "required": false}, {"kind": "field", "key": "account_name", "name": "Account Name / ชื่อบัญชี", "description": "收款账户名，标注 ชื่อบัญชี", "type": "string", "required": false}]}]'::json, '324a7d2562a45044fb88c9dc811b506585c972b9416865fe4bceca0f7f3e6e60', '2026-10-31 02:33:31.210651') ON CONFLICT DO NOTHING;
INSERT INTO document_template_versions (id, template_id, version, name, description, groups, content_hash, created_at) VALUES (3, 1, 2, 'Billing Note / ใบวางบิล', 'Thai Billing Note (ใบวางบิล): a supplier''s list of already-issued invoices / tax invoices asking the customer to pay by an agreed date; detail rows are invoices, not goods. Also called ใบแจ้งหนี้รวม or ใบวางบิล/ใบแจ้งหนี้. Typical features: the title contains ใบวางบิล or Billing Note; the body is an invoice list with one invoice per row and columns วันที่ใบแจ้งหนี้ / Invoice Date, เลขที่ใบแจ้งหนี้/ใบกำกับภาษี / Invoice No., จำนวนก่อนภาษีมูลค่าเพิ่ม / Amount, ภาษีมูลค่าเพิ่ม / Vat, จำนวนเงินรวม / Total Amount; the footer shows the invoice count (รวม N ฉบับ), the grand total payable (รวมยอดชำระทั้งสิ้น), the amount in Thai words, the receiving bank account, and sign-off boxes ผู้รับวางบิล / Received By and กำหนดชำระ / Payment Date. Unlike a single tax invoice, each detail row is an invoice rather than a product.', '[{"key": "document", "name": "Document / ข้อมูลเอกสาร", "description": "Document header information", "items": [{"kind": "field", "key": "billing_no", "name": "Billing No. / เลขที่ใบวางบิล", "description": "The billing note''s own number, labeled เลขที่ / No.; not the number of any invoice in the list. Many billing notes have no number; use null if absent", "type": "string", "required": false}, {"kind": "field", "key": "billing_date", "name": "Date / วันที่", "description": "Billing note date, labeled วันที่ / Date, usually to the right of the customer name. Keep as written (e.g. 22.02.2024); do not convert between Buddhist and Gregorian years", "type": "string", "required": true}, {"kind": "field", "key": "invoice_count", "name": "Invoice Count / จำนวนฉบับ", "description": "Number of invoices in the list, written like \"รวม 1 ฉบับ\"; digits only", "type": "integer", "required": false}, {"kind": "field", "key": "payment_due_date", "name": "Payment Date / กำหนดชำระ", "description": "Agreed payment date, labeled กำหนดชำระ / Payment Date / Due Date, often handwritten; use null if blank or only a dotted line. Keep as written", "type": "string", "required": false}, {"kind": "field", "key": "received_date", "name": "Received Date / วันที่รับวางบิล", "description": "Date the customer received the billing note, labeled วันที่รับวางบิล / Received Date, often handwritten; use null if blank. Keep as written", "type": "string", "required": false}]}, {"key": "issuer", "name": "Issuer / ผู้วางบิล", "description": "The supplier issuing the billing note (payee); details are usually in the page header next to the logo", "items": [{"kind": "field", "key": "name", "name": "Company Name / ชื่อบริษัท", "description": "Supplier''s full Thai name, e.g. \"ห้างหุ้นส่วนจำกัด …\" or \"บริษัท … จำกัด\"; keep as written", "type": "string", "required": true}, {"kind": "field", "key": "name_en", "name": "English Name / ชื่อภาษาอังกฤษ", "description": "Supplier''s English name (often below the logo or on the line under the Thai name); null if absent", "type": "string", "required": false}, {"kind": "field", "key": "tax_id", "name": "Tax ID / เลขประจำตัวผู้เสียภาษี", "description": "Supplier''s 13-digit taxpayer ID, labeled เลขประจำตัวผู้เสียภาษีอากร / Tax ID; digits only, no spaces or hyphens", "type": "string", "required": false}, {"kind": "field", "key": "branch", "name": "Branch / สาขา", "description": "Supplier branch, e.g. \"สำนักงานใหญ่\" (head office) or \"สาขาที่ 00001\"; keep as written", "type": "string", "required": false}, {"kind": "field", "key": "address", "name": "Address / ที่อยู่", "description": "Supplier''s full address, merged into one line", "type": "string", "required": false}, {"kind": "field", "key": "phone", "name": "Phone / โทร", "description": "Supplier phone, labeled โทร / Tel; separate multiple numbers with commas", "type": "string", "required": false}, {"kind": "field", "key": "email", "name": "Email / อีเมล", "description": "Supplier email, labeled อีเมล์ / Email", "type": "string", "required": false}]}, {"key": "customer", "name": "Customer / ลูกค้า", "description": "The customer who receives the billing note and must pay, labeled ชื่อลูกค้า / Customers", "items": [{"kind": "field", "key": "name", "name": "Customer Name / ชื่อลูกค้า", "description": "Customer''s full name; keep as written", "type": "string", "required": true}, {"kind": "field", "key": "tax_id", "name": "Tax ID / เลขประจำตัวผู้เสียภาษี", "description": "Customer''s 13-digit taxpayer ID; digits only; null if absent", "type": "string", "required": false}, {"kind": "field", "key": "branch", "name": "Branch / สาขา", "description": "Customer branch, e.g. \"สำนักงานใหญ่\"; null if absent", "type": "string", "required": false}, {"kind": "field", "key": "address", "name": "Address / ที่อยู่", "description": "Customer''s full address, merged into one line; null if absent", "type": "string", "required": false}]}, {"key": "invoices", "name": "Invoice List / รายการใบแจ้งหนี้", "description": "The list of invoices summarized by the billing note, often headed \"ได้รับวางบิล ตามรายการต่อไปนี้\"", "items": [{"kind": "table", "key": "items", "name": "Invoices / ใบแจ้งหนี้", "description": "One row per invoice or tax invoice; skip blank rows and do not treat bank account or total lines as rows; if the original (ต้นฉบับ) and copy (สำเนา) pages in the file are identical, output them only once", "columns": [{"key": "item_no", "name": "Item / ลำดับที่", "description": "Row number, labeled ลำดับที่ / Item", "type": "integer", "required": false}, {"key": "invoice_date", "name": "Invoice Date / วันที่ใบแจ้งหนี้", "description": "Date of this invoice, labeled วันที่ใบแจ้งหนี้/ใบกำกับภาษี / Invoice Date; keep as written", "type": "string", "required": false}, {"key": "invoice_no", "name": "Invoice No. / เลขที่ใบแจ้งหนี้", "description": "Number of this invoice, labeled เลขที่ใบแจ้งหนี้และ/หรือใบกำกับภาษี / Invoice/Tax Invoice No., e.g. INV2024020872", "type": "string", "required": true}, {"key": "product", "name": "Product / สินค้า", "description": "Product or summary for this invoice, labeled สินค้า / Product; null if absent", "type": "string", "required": false}, {"key": "delivery_date", "name": "Send Date / วันที่ส่งสินค้า", "description": "Delivery date, labeled วันที่ส่งสินค้า / Send Date; null if blank", "type": "string", "required": false}, {"key": "amount_before_vat", "name": "Amount / ก่อนภาษีมูลค่าเพิ่ม", "description": "Amount excluding VAT, labeled จำนวนก่อนภาษีมูลค่าเพิ่ม / Amount", "type": "amount", "required": false}, {"key": "vat_amount", "name": "VAT / ภาษีมูลค่าเพิ่ม", "description": "VAT amount, labeled ภาษีมูลค่าเพิ่ม / Vat", "type": "amount", "required": false}, {"key": "total_amount", "name": "Total Amount / จำนวนเงินรวม", "description": "Total of this invoice including VAT, labeled จำนวนเงินรวม / Total Amount", "type": "amount", "required": true}]}]}, {"key": "summary", "name": "Summary / สรุปยอด", "description": "Totals at the bottom of the billing note", "items": [{"kind": "field", "key": "total_amount", "name": "Grand Total / รวมยอดชำระทั้งสิ้น", "description": "Grand total payable, labeled รวมยอดชำระทั้งสิ้น (บาท); take the number as written, do not add it up yourself", "type": "amount", "required": true}, {"kind": "field", "key": "total_amount_text", "name": "Amount in Words / จำนวนเงินตัวอักษร", "description": "Amount in Thai words, labeled (ตัวอักษร), e.g. \"หกพันหกร้อยหกสิบหกบาทสามสิบเอ็ดสตางค์\"; keep as written", "type": "string", "required": false}]}, {"key": "payment", "name": "Payment / การชำระเงิน", "description": "Receiving bank account, usually written below the invoice list, e.g. \"เลขที่บัญชีสำหรับโอนเงิน ธนาคาร …\"", "items": [{"kind": "field", "key": "bank_name", "name": "Bank / ธนาคาร", "description": "Receiving bank name, e.g. \"ธนาคาร กสิกรไทย\"", "type": "string", "required": false}, {"kind": "field", "key": "account_no", "name": "Account No. / เลขที่บัญชี", "description": "Receiving bank account number; keep only digits and hyphens, remove quotes and other symbols", "type": "string", "required": false}, {"kind": "field", "key": "account_name", "name": "Account Name / ชื่อบัญชี", "description": "Receiving account name, labeled ชื่อบัญชี", "type": "string", "required": false}]}]'::json, '5e305c22394a3ac14b8fd829c1866d87cbafd75f03acce6aea4f2be696b4f067', '2026-11-01 07:01:31.156712') ON CONFLICT DO NOTHING;
INSERT INTO document_template_versions (id, template_id, version, name, description, groups, content_hash, created_at) VALUES (2, 2, 1, 'Tax Invoice / ใบกำกับภาษี', '泰国「ใบกำกับภาษี / Tax Invoice」，包括合并单据「ใบกำกับภาษี/ใบส่งของ (Tax Invoice / Delivery Order)」「ใบแจ้งหนี้/ใบกำกับภาษี」「ใบส่งสินค้า/ใบกำกับภาษี」，以及原件（ต้นฉบับ）与副本（สำเนา）。典型特征：标题含 ใบกำกับภาษี 或 Tax Invoice；有卖方与买方的 13 位税号；有单据编号 ใบกำกับภาษีเลขที่ / Tax Invoice No. 与日期；正文是货品明细表（ลำดับ Seq、รายการสินค้า Description、จำนวน Quantity、หน่วย Unit、ราคา Price、ส่วนลด Discount、จำนวนเงิน Amount）；底部有 รวมเงิน Sub Total、ส่วนลด Discount、ภาษีมูลค่าเพิ่ม Vat 7%、รวมเงินสุทธิ Net Total、泰文大写金额，以及 ผู้ส่งของ / ผู้รับของ 签收栏。与 ใบวางบิล（Billing Note）的区别：明细行是「货品」而不是「发票」。', '[{"key": "document", "name": "Document / ข้อมูลเอกสาร", "description": "单据头部信息，通常在右上角的方框内", "items": [{"kind": "field", "key": "invoice_no", "name": "Tax Invoice No. / เลขที่ใบกำกับภาษี", "description": "单据编号，标注 ใบกำกับภาษีเลขที่ / Tax Invoice No. / เลขที่，如 IV69100017", "type": "string", "required": true}, {"kind": "field", "key": "invoice_date", "name": "Date / วันที่", "description": "开票日期，标注 วันที่ / Date。按原文保留（如 01/10/2026），不转换佛历或公历", "type": "string", "required": true}, {"kind": "field", "key": "document_title", "name": "Document Title / ชื่อเอกสาร", "description": "单据标题原文，含原件 / 副本标识，如「ต้นฉบับใบกำกับภาษี / ใบส่งของ TAX INVOICE ORIGINAL / DELIVERY ORDER」", "type": "string", "required": false}, {"kind": "field", "key": "customer_code", "name": "Customer Code / รหัสลูกค้า", "description": "客户编码，标注 รหัสลูกค้า / Cust Code", "type": "string", "required": false}, {"kind": "field", "key": "customer_po_no", "name": "Customer PO No. / เลขที่ใบสั่งซื้อ", "description": "客户采购单号，标注 เลขที่ใบสั่งซื้อ / Customer PO No. / P/O No.，用于与采购单对账", "type": "string", "required": false}, {"kind": "field", "key": "salesman", "name": "Salesman / พนักงานขาย", "description": "销售代表，标注 ตัวแทนขาย / พนักงานขาย / Salesman", "type": "string", "required": false}, {"kind": "field", "key": "payment_term", "name": "Payment Term / เงื่อนไขการชำระ", "description": "付款条件，标注 กำหนดชำระ / เงื่อนไขการชำระเงิน / Term / Credit，如「เงินสด」（现金）或「30 วัน」，按原文保留", "type": "string", "required": false}, {"kind": "field", "key": "due_date", "name": "Due Date / วันครบกำหนด", "description": "到期付款日期，标注 วันครบกำหนด / Due Date；文档中没有具体日期时填 null，不要根据付款条件推算", "type": "string", "required": false}]}, {"key": "seller", "name": "Seller / ผู้ขาย", "description": "开具发票的卖方，信息通常在页面顶部抬头与 Logo 旁", "items": [{"kind": "field", "key": "name", "name": "Company Name / ชื่อบริษัท", "description": "卖方泰文全称，如「บริษัท เค สยาม กรุ๊ป จำกัด」，按原文保留", "type": "string", "required": true}, {"kind": "field", "key": "name_en", "name": "English Name / ชื่อภาษาอังกฤษ", "description": "卖方英文名称，如「K SIAM GROUP CO., LTD.」，没有填 null", "type": "string", "required": false}, {"kind": "field", "key": "tax_id", "name": "Tax ID / เลขประจำตัวผู้เสียภาษี", "description": "卖方 13 位纳税人识别号，标注 เลขประจำตัวผู้เสียภาษีอากร；只填数字，不含空格和横线", "type": "string", "required": true}, {"kind": "field", "key": "branch", "name": "Branch / สาขา", "description": "卖方分支机构，如「สำนักงานใหญ่」（总公司）或「สาขาที่ 00001」；原文地址以「สำนักงานใหญ่ :」开头时也填在这里", "type": "string", "required": false}, {"kind": "field", "key": "address", "name": "Address / ที่อยู่", "description": "卖方地址全文，合并为一行，不含「สำนักงานใหญ่ :」前缀", "type": "string", "required": false}, {"kind": "field", "key": "phone", "name": "Phone / โทร", "description": "卖方电话，标注 โทร / Tel；多个号码用英文逗号分隔", "type": "string", "required": false}, {"kind": "field", "key": "fax", "name": "Fax / แฟกซ์", "description": "卖方传真，标注 แฟกซ์ / Fax，没有填 null", "type": "string", "required": false}]}, {"key": "buyer", "name": "Buyer / ผู้ซื้อ", "description": "购买方（客户），标注 ลูกค้า / Customer / ผู้ซื้อ / Sold To", "items": [{"kind": "field", "key": "name", "name": "Customer Name / ชื่อลูกค้า", "description": "买方名称全文，按原文保留", "type": "string", "required": true}, {"kind": "field", "key": "tax_id", "name": "Tax ID / เลขประจำตัวผู้เสียภาษี", "description": "买方 13 位纳税人识别号，标注 เลขประจำตัวผู้เสียภาษี；只填数字", "type": "string", "required": false}, {"kind": "field", "key": "branch", "name": "Branch / สาขา", "description": "买方分支机构，常紧跟在买方税号后面，如「สำนักงานใหญ่」", "type": "string", "required": false}, {"kind": "field", "key": "address", "name": "Address / ที่อยู่", "description": "买方地址全文，合并为一行", "type": "string", "required": false}]}, {"key": "goods", "name": "Items / รายการสินค้า", "description": "货品明细表", "items": [{"kind": "table", "key": "line_items", "name": "Line Items / รายการสินค้า", "description": "每一行对应原文中的一个序号（ลำดับ / Seq）；同一序号下跨多行的品名、规格说明合并为该行的 description；忽略空白行；文件中原件（ต้นฉบับ）与副本（สำเนา）页内容相同时只输出一份", "columns": [{"key": "seq", "name": "Seq / ลำดับ", "description": "行序号，标注 ลำดับ / Seq / No.", "type": "integer", "required": false}, {"key": "product_code", "name": "Product Code / รหัสสินค้า", "description": "商品编码，标注 รหัสสินค้า / Code；没有该列时填 null", "type": "string", "required": false}, {"key": "description", "name": "Description / รายการสินค้า", "description": "品名及规格全文，标注 รายการสินค้า / Description；把同一序号下的多行合并为一行，但不包含单独写出的「PO : …」行", "type": "string", "required": true}, {"key": "po_no", "name": "PO No. / เลขที่ใบสั่งซื้อ", "description": "该行注明的采购单号，原文形如「PO : PS260900055」，只填单号；没有填 null", "type": "string", "required": false}, {"key": "quantity", "name": "Quantity / จำนวน", "description": "数量，标注 จำนวน / Quantity / Qty，只填数字", "type": "decimal", "required": false}, {"key": "unit", "name": "Unit / หน่วย", "description": "计量单位，标注 หน่วย / Unit，如「แผ่น」「ชิ้น」「กล่อง」", "type": "string", "required": false}, {"key": "unit_price", "name": "Unit Price / ราคาต่อหน่วย", "description": "单价，标注 ราคา / ราคาต่อหน่วย / Price / Unit Price；按原文小数位保留", "type": "decimal", "required": false}, {"key": "discount", "name": "Discount / ส่วนลด", "description": "该行折扣，标注 ส่วนลด / Discount，可能是金额或百分比（如 5%），按原文保留；空白填 null", "type": "string", "required": false}, {"key": "amount", "name": "Amount / จำนวนเงิน", "description": "该行金额，标注 จำนวนเงิน / Amount；直接取原文数字，不要用数量 × 单价计算", "type": "amount", "required": true}]}]}, {"key": "summary", "name": "Summary / สรุปยอด", "description": "明细表下方的合计区；所有金额直接取原文，不要自行计算", "items": [{"kind": "field", "key": "sub_total", "name": "Sub Total / รวมเงิน", "description": "货品合计（折扣前），标注 รวมเงิน / Sub Total", "type": "amount", "required": false}, {"kind": "field", "key": "discount_rate", "name": "Discount Rate / อัตราส่วนลด", "description": "整单折扣比例，写在 ส่วนลด (Discount) 旁，如「2%」，按原文保留；没有填 null", "type": "string", "required": false}, {"kind": "field", "key": "discount_amount", "name": "Discount / ส่วนลด", "description": "整单折扣金额，标注 ส่วนลด / Discount；没有填 null", "type": "amount", "required": false}, {"kind": "field", "key": "total_before_vat", "name": "Total before VAT / รวมค่าสินค้า", "description": "折扣后、税前金额，标注 รวมค่าสินค้า / มูลค่าสินค้า / Total / Amount before VAT", "type": "amount", "required": false}, {"kind": "field", "key": "vat_rate", "name": "VAT Rate / อัตราภาษี", "description": "增值税税率，写在 ภาษีมูลค่าเพิ่ม (Vat) 旁，如「7%」，按原文保留", "type": "string", "required": false}, {"kind": "field", "key": "vat_amount", "name": "VAT / ภาษีมูลค่าเพิ่ม", "description": "增值税额，标注 ภาษีมูลค่าเพิ่ม / Vat", "type": "amount", "required": false}, {"kind": "field", "key": "net_total", "name": "Net Total / รวมเงินสุทธิ", "description": "含税应付总额，标注 รวมเงินสุทธิ / จำนวนเงินรวมทั้งสิ้น / Net Total / Grand Total", "type": "amount", "required": true}, {"kind": "field", "key": "amount_in_words", "name": "Amount in Words / จำนวนเงินตัวอักษร", "description": "泰文大写金额，通常在合计区左侧括号内，如「(เจ็ดหมื่นหนึ่งพัน…สตางค์)」，去掉外层括号，其余按原文保留", "type": "string", "required": false}]}, {"key": "delivery", "name": "Delivery / การส่งของ", "description": "页面底部的送货与签收栏，多为手写；空白或只有虚线时填 null", "items": [{"kind": "field", "key": "delivered_by", "name": "Delivered By / ผู้ส่งของ", "description": "送货人姓名，写在 ผู้ส่งของ / Delivered By 附近", "type": "string", "required": false}, {"kind": "field", "key": "delivery_date", "name": "Delivery Date / วันที่ส่ง", "description": "送货日期，写在 ผู้ส่งของ 那一行的 วันที่ / Date 处，按原文保留", "type": "string", "required": false}, {"kind": "field", "key": "vehicle_no", "name": "Vehicle No. / ทะเบียนรถ", "description": "送货车辆车牌号，标注 ทะเบียนรถ，如「70-1713」", "type": "string", "required": false}, {"kind": "field", "key": "received_by", "name": "Received By / ผู้รับของ", "description": "收货人姓名，写在 ผู้รับของ / Receiver 附近", "type": "string", "required": false}, {"kind": "field", "key": "received_date", "name": "Received Date / วันที่รับ", "description": "收货日期，写在 ผู้รับของ 那一行的 วันที่ / Date 处，按原文保留", "type": "string", "required": false}]}, {"key": "other", "name": "Other / อื่นๆ", "description": "备注", "items": [{"kind": "field", "key": "remark", "name": "Remark / หมายเหตุ", "description": "备注框（หมายเหตุ / Remark）里填写的内容；印刷的固定条款（如「(1) ได้รับสินค้าตามรายการ…」）不算备注；空白填 null", "type": "string", "required": false}]}]'::json, 'f1a71c857fa554adaf2e97207c780dfdafa094f8746da0b0fc61d0b3345fd65f', '2026-10-31 02:33:32.417372') ON CONFLICT DO NOTHING;
INSERT INTO document_template_versions (id, template_id, version, name, description, groups, content_hash, created_at) VALUES (4, 2, 2, 'Tax Invoice / ใบกำกับภาษี', 'Thai Tax Invoice (ใบกำกับภาษี) for goods sold, with seller and buyer 13-digit tax IDs; detail rows are goods, not invoices. Includes combined documents ใบกำกับภาษี/ใบส่งของ (Tax Invoice / Delivery Order), ใบแจ้งหนี้/ใบกำกับภาษี and ใบส่งสินค้า/ใบกำกับภาษี, both original (ต้นฉบับ) and copy (สำเนา). Typical features: the title contains ใบกำกับภาษี or Tax Invoice; there is a document number ใบกำกับภาษีเลขที่ / Tax Invoice No. and a date; the body is a goods table (ลำดับ Seq, รายการสินค้า Description, จำนวน Quantity, หน่วย Unit, ราคา Price, ส่วนลด Discount, จำนวนเงิน Amount); the footer has รวมเงิน Sub Total, ส่วนลด Discount, ภาษีมูลค่าเพิ่ม Vat 7%, รวมเงินสุทธิ Net Total, the amount in Thai words, and ผู้ส่งของ / ผู้รับของ sign-off boxes. Unlike a Billing Note (ใบวางบิล), each detail row is a product rather than an invoice.', '[{"key": "document", "name": "Document / ข้อมูลเอกสาร", "description": "Document header information, usually in the box at the top right", "items": [{"kind": "field", "key": "invoice_no", "name": "Tax Invoice No. / เลขที่ใบกำกับภาษี", "description": "Document number, labeled ใบกำกับภาษีเลขที่ / Tax Invoice No. / เลขที่, e.g. IV69100017", "type": "string", "required": true}, {"kind": "field", "key": "invoice_date", "name": "Date / วันที่", "description": "Issue date, labeled วันที่ / Date. Keep as written (e.g. 01/10/2026); do not convert between Buddhist and Gregorian years", "type": "string", "required": true}, {"kind": "field", "key": "document_title", "name": "Document Title / ชื่อเอกสาร", "description": "Document title as written, including the original / copy marker, e.g. \"ต้นฉบับใบกำกับภาษี / ใบส่งของ TAX INVOICE ORIGINAL / DELIVERY ORDER\"", "type": "string", "required": false}, {"kind": "field", "key": "customer_code", "name": "Customer Code / รหัสลูกค้า", "description": "Customer code, labeled รหัสลูกค้า / Cust Code", "type": "string", "required": false}, {"kind": "field", "key": "customer_po_no", "name": "Customer PO No. / เลขที่ใบสั่งซื้อ", "description": "Customer purchase order number, labeled เลขที่ใบสั่งซื้อ / Customer PO No. / P/O No.; used to reconcile against the purchase order", "type": "string", "required": false}, {"kind": "field", "key": "salesman", "name": "Salesman / พนักงานขาย", "description": "Sales representative, labeled ตัวแทนขาย / พนักงานขาย / Salesman", "type": "string", "required": false}, {"kind": "field", "key": "payment_term", "name": "Payment Term / เงื่อนไขการชำระ", "description": "Payment terms, labeled กำหนดชำระ / เงื่อนไขการชำระเงิน / Term / Credit, e.g. \"เงินสด\" (cash) or \"30 วัน\"; keep as written", "type": "string", "required": false}, {"kind": "field", "key": "due_date", "name": "Due Date / วันครบกำหนด", "description": "Payment due date, labeled วันครบกำหนด / Due Date; use null if no explicit date appears, do not derive it from the payment terms", "type": "string", "required": false}]}, {"key": "seller", "name": "Seller / ผู้ขาย", "description": "The seller issuing the invoice; details are usually in the page header next to the logo", "items": [{"kind": "field", "key": "name", "name": "Company Name / ชื่อบริษัท", "description": "Seller''s full Thai name, e.g. \"บริษัท เค สยาม กรุ๊ป จำกัด\"; keep as written", "type": "string", "required": true}, {"kind": "field", "key": "name_en", "name": "English Name / ชื่อภาษาอังกฤษ", "description": "Seller''s English name, e.g. \"K SIAM GROUP CO., LTD.\"; null if absent", "type": "string", "required": false}, {"kind": "field", "key": "tax_id", "name": "Tax ID / เลขประจำตัวผู้เสียภาษี", "description": "Seller''s 13-digit taxpayer ID, labeled เลขประจำตัวผู้เสียภาษีอากร; digits only, no spaces or hyphens", "type": "string", "required": true}, {"kind": "field", "key": "branch", "name": "Branch / สาขา", "description": "Seller branch, e.g. \"สำนักงานใหญ่\" (head office) or \"สาขาที่ 00001\"; also fill this when the address starts with \"สำนักงานใหญ่ :\"", "type": "string", "required": false}, {"kind": "field", "key": "address", "name": "Address / ที่อยู่", "description": "Seller''s full address, merged into one line, without the \"สำนักงานใหญ่ :\" prefix", "type": "string", "required": false}, {"kind": "field", "key": "phone", "name": "Phone / โทร", "description": "Seller phone, labeled โทร / Tel; separate multiple numbers with commas", "type": "string", "required": false}, {"kind": "field", "key": "fax", "name": "Fax / แฟกซ์", "description": "Seller fax, labeled แฟกซ์ / Fax; null if absent", "type": "string", "required": false}]}, {"key": "buyer", "name": "Buyer / ผู้ซื้อ", "description": "The buyer (customer), labeled ลูกค้า / Customer / ผู้ซื้อ / Sold To", "items": [{"kind": "field", "key": "name", "name": "Customer Name / ชื่อลูกค้า", "description": "Buyer''s full name; keep as written", "type": "string", "required": true}, {"kind": "field", "key": "tax_id", "name": "Tax ID / เลขประจำตัวผู้เสียภาษี", "description": "Buyer''s 13-digit taxpayer ID, labeled เลขประจำตัวผู้เสียภาษี; digits only", "type": "string", "required": false}, {"kind": "field", "key": "branch", "name": "Branch / สาขา", "description": "Buyer branch, often right after the buyer''s tax ID, e.g. \"สำนักงานใหญ่\"", "type": "string", "required": false}, {"kind": "field", "key": "address", "name": "Address / ที่อยู่", "description": "Buyer''s full address, merged into one line", "type": "string", "required": false}]}, {"key": "goods", "name": "Items / รายการสินค้า", "description": "Goods detail table", "items": [{"kind": "table", "key": "line_items", "name": "Line Items / รายการสินค้า", "description": "One row per sequence number (ลำดับ / Seq) in the document; merge product name and specification lines spanning several lines under the same number into that row''s description; skip blank rows; if the original (ต้นฉบับ) and copy (สำเนา) pages in the file are identical, output them only once", "columns": [{"key": "seq", "name": "Seq / ลำดับ", "description": "Row number, labeled ลำดับ / Seq / No.", "type": "integer", "required": false}, {"key": "product_code", "name": "Product Code / รหัสสินค้า", "description": "Product code, labeled รหัสสินค้า / Code; null if the column does not exist", "type": "string", "required": false}, {"key": "description", "name": "Description / รายการสินค้า", "description": "Full product name and specification, labeled รายการสินค้า / Description; merge multiple lines under the same number into one line, but exclude a separate \"PO : …\" line", "type": "string", "required": true}, {"key": "po_no", "name": "PO No. / เลขที่ใบสั่งซื้อ", "description": "Purchase order number noted on this row, written like \"PO : PS260900055\"; number only; null if absent", "type": "string", "required": false}, {"key": "quantity", "name": "Quantity / จำนวน", "description": "Quantity, labeled จำนวน / Quantity / Qty; digits only", "type": "decimal", "required": false}, {"key": "unit", "name": "Unit / หน่วย", "description": "Unit of measure, labeled หน่วย / Unit, e.g. \"แผ่น\", \"ชิ้น\", \"กล่อง\"", "type": "string", "required": false}, {"key": "unit_price", "name": "Unit Price / ราคาต่อหน่วย", "description": "Unit price, labeled ราคา / ราคาต่อหน่วย / Price / Unit Price; keep the decimal places as written", "type": "decimal", "required": false}, {"key": "discount", "name": "Discount / ส่วนลด", "description": "Line discount, labeled ส่วนลด / Discount; may be an amount or a percentage (e.g. 5%); keep as written; null if blank", "type": "string", "required": false}, {"key": "amount", "name": "Amount / จำนวนเงิน", "description": "Line amount, labeled จำนวนเงิน / Amount; take the number as written, do not compute quantity × unit price", "type": "amount", "required": true}]}]}, {"key": "summary", "name": "Summary / สรุปยอด", "description": "Totals area below the detail table; take every amount as written, do not calculate", "items": [{"kind": "field", "key": "sub_total", "name": "Sub Total / รวมเงิน", "description": "Goods total before discount, labeled รวมเงิน / Sub Total", "type": "amount", "required": false}, {"kind": "field", "key": "discount_rate", "name": "Discount Rate / อัตราส่วนลด", "description": "Document-level discount rate, written next to ส่วนลด (Discount), e.g. \"2%\"; keep as written; null if absent", "type": "string", "required": false}, {"kind": "field", "key": "discount_amount", "name": "Discount / ส่วนลด", "description": "Document-level discount amount, labeled ส่วนลด / Discount; null if absent", "type": "amount", "required": false}, {"kind": "field", "key": "total_before_vat", "name": "Total before VAT / รวมค่าสินค้า", "description": "Amount after discount and before VAT, labeled รวมค่าสินค้า / มูลค่าสินค้า / Total / Amount before VAT", "type": "amount", "required": false}, {"kind": "field", "key": "vat_rate", "name": "VAT Rate / อัตราภาษี", "description": "VAT rate, written next to ภาษีมูลค่าเพิ่ม (Vat), e.g. \"7%\"; keep as written", "type": "string", "required": false}, {"kind": "field", "key": "vat_amount", "name": "VAT / ภาษีมูลค่าเพิ่ม", "description": "VAT amount, labeled ภาษีมูลค่าเพิ่ม / Vat", "type": "amount", "required": false}, {"kind": "field", "key": "net_total", "name": "Net Total / รวมเงินสุทธิ", "description": "Total payable including VAT, labeled รวมเงินสุทธิ / จำนวนเงินรวมทั้งสิ้น / Net Total / Grand Total", "type": "amount", "required": true}, {"kind": "field", "key": "amount_in_words", "name": "Amount in Words / จำนวนเงินตัวอักษร", "description": "Amount in Thai words, usually in parentheses on the left of the totals area, e.g. \"(เจ็ดหมื่นหนึ่งพัน…สตางค์)\"; remove the outer parentheses and keep the rest as written", "type": "string", "required": false}]}, {"key": "delivery", "name": "Delivery / การส่งของ", "description": "Delivery and sign-off boxes at the bottom of the page, mostly handwritten; use null if blank or only a dotted line", "items": [{"kind": "field", "key": "delivered_by", "name": "Delivered By / ผู้ส่งของ", "description": "Name of the person delivering, written near ผู้ส่งของ / Delivered By", "type": "string", "required": false}, {"kind": "field", "key": "delivery_date", "name": "Delivery Date / วันที่ส่ง", "description": "Delivery date, written at วันที่ / Date on the ผู้ส่งของ line; keep as written", "type": "string", "required": false}, {"kind": "field", "key": "vehicle_no", "name": "Vehicle No. / ทะเบียนรถ", "description": "Delivery vehicle licence plate, labeled ทะเบียนรถ, e.g. \"70-1713\"", "type": "string", "required": false}, {"kind": "field", "key": "received_by", "name": "Received By / ผู้รับของ", "description": "Name of the person receiving, written near ผู้รับของ / Receiver", "type": "string", "required": false}, {"kind": "field", "key": "received_date", "name": "Received Date / วันที่รับ", "description": "Receiving date, written at วันที่ / Date on the ผู้รับของ line; keep as written", "type": "string", "required": false}]}, {"key": "other", "name": "Other / อื่นๆ", "description": "Remarks", "items": [{"kind": "field", "key": "remark", "name": "Remark / หมายเหตุ", "description": "Content written in the remark box (หมายเหตุ / Remark); printed standard terms (e.g. \"(1) ได้รับสินค้าตามรายการ…\") are not remarks; null if blank", "type": "string", "required": false}]}]'::json, 'cbf89b919f50a0c7c44c0994c417f240a24c033b82074f16c548d82dbf10ae40', '2026-11-01 07:01:33.788112') ON CONFLICT DO NOTHING;

-- 自增序列对齐到已导入的最大 id
SELECT setval(pg_get_serial_sequence('plans', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM plans), 1), (SELECT COUNT(*) > 0 FROM plans));
SELECT setval(pg_get_serial_sequence('document_templates', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM document_templates), 1), (SELECT COUNT(*) > 0 FROM document_templates));
SELECT setval(pg_get_serial_sequence('document_template_versions', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM document_template_versions), 1), (SELECT COUNT(*) > 0 FROM document_template_versions));

COMMIT;
